 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    # The same separator color forms the complete grid-spanning dividers.
    sep = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]
    row_spans, start = [], 0
    for r in range(h):
        if r in sep_rows:
            if start < r:
                row_spans.append((start, r))
            start = r + 1
    if start < h:
        row_spans.append((start, h))
    col_spans, start = [], 0
    for c in range(w):
        if c in sep_cols:
            if start < c:
                col_spans.append((start, c))
            start = c + 1
    if start < w:
        col_spans.append((start, w))
    vals = [grid[r][c] for r in range(h) for c in range(w) if r not in sep_rows and c not in sep_cols]
    bg = Counter(vals).most_common(1)[0][0]
    return [[1 if sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)) == 2 else bg
             for c0, c1 in col_spans] for r0, r1 in row_spans]
